{
  "a_sentences": [
    {
      "a_text": "Le litige porte sur la condamnation de l'intimé à restituer aux assureurs-maladie les montants de 160'371 fr. pour l'année statistique 2016 et de 206'586 fr. pour l'année statistique 2017, perçus sur la base de prestations facturées en fonction de positions TARMED pour lesquelles il ne disposait pas de la valeur intrinsèque qualitative requise.",
      "b_propositions": ["P1"]
    },
    {
      "a_text": "Selon les constatations du tribunal arbitral, l'intimé a obtenu le titre de médecin praticien en 2011 et exerce la médecine en Suisse depuis cette date.",
      "b_propositions": ["P2"]
    },
    {
      "a_text": "La prise en charge des coûts des prestations est régie par l'art. 32 al. 1 LAMal en relation avec l'art. 25 al. 1 et 2 LAMal, sur la base de tarifs ou de prix tels que la structure tarifaire TARMED.",
      "b_propositions": ["P3"]
    },
    {
      "a_text": "Santésuisse est habilitée à agir pour le compte des caisses-maladie membres conformément à ses statuts et, pour les non-membres, sur la base d'un mandat de représentation valable selon les règles générales du CO.",
      "b_propositions": ["P4"]
    },
    {
      "a_text": "La maxime inquisitoire s'applique dans les procédures fondées sur l'art. 56 al. 2 LAMal.",
      "b_propositions": ["P5"]
    },
    {
      "a_text": "Le tribunal arbitral a retenu qu'il n'existait pas de statistiques fiables pour déterminer le caractère économique de la pratique de l'intimé, car les indices ANOVA et de régression avaient été calculés en incluant les montants déjà réclamés en restitution.",
      "b_propositions": ["P6"]
    },
    {
      "a_text": "Ce raisonnement est jugé incomplet ou insuffisant au regard de la maxime inquisitoire.",
      "b_propositions": ["P7"]
    },
    {
      "a_text": "Le jugement attaqué est annulé sur ce point et la cause renvoyée au Tribunal arbitral pour qu'il complète l'instruction avec l'aide des assureurs-maladie.",
      "b_propositions": ["P8"]
    }
  ]
}
